// ============================================================
// ACHIEVEMENT HOOKS
// ============================================================
function wireAchievements(){
  const award = (id) => {
    const s = SaveSystem.load();
    s.achievements = s.achievements || {};
    if(!s.achievements[id]){
      s.achievements[id] = true;
      SaveSystem.save(s);
      bus.emit('ACHIEVEMENT_UNLOCKED', {id});
    }
  };
  bus.on('COIN_COLLECTED', () => award('first_coin'));
  bus.on('ENEMY_KILLED',   () => award('first_kill'));
  bus.on('STAGE_COMPLETED',() => award('first_stage'));
  bus.on('CHECKPOINT_REACHED', () => award('checkpoint'));
}

// ============================================================
// BOOTSTRAP
// ============================================================
function boot(){
  wireAchievements();
  PlatformAdapter.init();

  const config = {
    type: Phaser.AUTO,
    parent: 'game',
    backgroundColor: '#0a0a12',
    scale: { mode: Phaser.Scale.FIT, autoCenter: Phaser.Scale.CENTER_BOTH, width: 960, height: 540 },
    physics: { default: 'arcade', arcade: { gravity:{y:0}, debug: ENGINE_CONFIG.debug } },
    scene: [BootScene, PreloadScene, MenuScene, GameScene, HUDScene, PauseScene, ResultScene, UpgradeScene, SettingsScene, AchievementsScene],
    render: { pixelArt: false, antialias: true }
  };
  new Phaser.Game(config);
}

boot();
